package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.SQLException;
import java.util.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import org.apache.commons.codec.digest.DigestUtils;

/** Native signed intake adds payload integrity to the existing table-scoped API-key authority. */
final class SignedEvents {
 private SignedEvents() {}
 static Map<String,Object> profile(Store.Db db,String id)throws SQLException {var row=db.one("SELECT profile_id,name,table_name,gateway_id,definition,active,revision FROM os_signed_profile WHERE profile_id=?",id);if(row==null)throw new Failure(404,"Integration profile not found");return row;}
 static Map<String,Object> definition(Store.Db db,Object input)throws SQLException {
  var body=object(input);require(body.keySet().equals(Set.of("name","table","gateway_username","fields")),"Provide name, table, gateway username and allowed fields");String name=WorkJobs.text(body.get("name"),160),table=WorkJobs.text(body.get("table"),80),username=WorkJobs.text(body.get("gateway_username"),80);var schema=Service.schema(db,table);RecordPolicy.require(schema,"read",db.viewerRole);var user=db.one("SELECT user_id FROM os_user WHERE name=?",username);require(user!=null,"Choose an existing gateway account");String gateway=user.get("user_id").toString();InboundMail.gateway(db,gateway);require(body.get("fields") instanceof List<?> list && !list.isEmpty() && list.size()<=32,"Choose one to32 allowed record fields");var fields=new TreeSet<String>();for(Object field:(List<?>)body.get("fields")){require(field instanceof String && object(schema.get("fields")).containsKey(field) && fields.add((String)field),"Choose unique current record fields");}require(fields.contains("short_description"),"Allow the record summary field");return map("name",name,"table",table,"gateway_id",gateway,"fields",new ArrayList<>(fields));
 }
 static Map<String,Object> page(Store.Db db,String id,Map<String,String> args)throws SQLException {
  Service.requireAccountAdministrator(db,db.viewerId);require(Set.of("table").containsAll(args.keySet()),"Choose only a record type");var selected=id.isEmpty()?null:profile(db,id);String table=selected==null?args.getOrDefault("table","incident"):selected.get("table_name").toString();var schema=Service.schema(db,table);RecordPolicy.require(schema,"read",db.viewerRole);var entries=new ArrayList<Map<String,Object>>();if(selected!=null)for(var row:db.all("SELECT event_id,record_id,profile_revision,created FROM os_signed_receipt WHERE profile_id=? ORDER BY created DESC,event_id LIMIT 100",id)){String record=row.remove("record_id").toString();Map<String,Object> visible=map();try{visible=FieldAccess.serialize(db,Service.readRecord(db,table,record));}catch(Failure unavailable){ /* Retain event evidence while suppressing unavailable record data. */ }row.put("record",visible);entries.add(row);}var tables=new ArrayList<Map<String,Object>>();for(var row:db.all("SELECT name,definition FROM os_schema ORDER BY name"))tables.add(map("name",row.get("name"),"label",object(row.get("definition")).get("label")));var config=selected==null?map("name","","table",table,"gateway_id","","fields",List.of("short_description","description")):object(selected.get("definition"));String gateway=config.get("gateway_id").toString();return map("profiles",db.all("SELECT profile_id,name,table_name,active,revision FROM os_signed_profile ORDER BY name,profile_id"),"profile",selected==null?map("profile_id","","revision",0,"active",1):selected,"definition",config,"tables",tables,"fields",schema.get("fields"),"gateway_name",gateway.isEmpty()?"":db.one("SELECT COALESCE((SELECT name FROM os_user WHERE user_id=?),'Unavailable gateway') AS name",gateway).get("name"),"receipts",entries,"total",id.isEmpty()?0:db.count("SELECT COUNT(*) FROM os_signed_receipt WHERE profile_id=?",id));
 }
 static Map<String,Object> form(Map<String,String> input){
  var form=new LinkedHashMap<>(input);form.remove("csrf");if(form.keySet().equals(Set.of("revision","operation")))return map("revision",Service.number(form.get("revision"),1,Integer.MAX_VALUE),"operation",form.get("operation"));require(Set.of("true","false").contains(form.getOrDefault("active","")),"Choose profile availability");var result=map("revision",Service.number(form.getOrDefault("revision",""),0,Integer.MAX_VALUE),"active",Boolean.valueOf(form.get("active")));if(form.keySet().equals(Set.of("revision","active")))return result;var fields=new ArrayList<String>();for(String key:new ArrayList<>(form.keySet()))if(key.startsWith("field_")){require(form.remove(key).equals("true"),"Choose allowed record fields");fields.add(key.substring(6));}require(form.keySet().equals(Set.of("revision","active","name","table","gateway_username")),"Provide the current integration form fields");result.put("definition",map("name",form.get("name"),"table",form.get("table"),"gateway_username",form.get("gateway_username"),"fields",fields));return result;
 }
 static Map<String,Object> save(Store store,Store.Db db,String id,Object input)throws Exception {
  if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");Service.requireAccountAdministrator(db,db.viewerId);var body=object(input);var before=id.isEmpty()?null:profile(db,id);ProblemInvestigations.revision(body.get("revision"),before==null?0:before.get("revision"));boolean rotate=body.keySet().equals(Set.of("revision","operation"));String secret="";
  if(rotate){require(before!=null && "rotate".equals(body.get("operation")),"Rotate an existing profile secret");secret="osw_"+Passwords.token()+Passwords.token();db.update("UPDATE os_signed_profile SET envelope=?,revision=revision+1 WHERE profile_id=?",Outbox.encrypt(store.secret,JSON.writeValueAsString(map("secret",secret))),id);}
  else{require((body.keySet().equals(Set.of("revision","active","definition")) || body.keySet().equals(Set.of("revision","active"))) && body.get("active") instanceof Boolean,"Provide revision, Boolean active and optional definition");require(before!=null || body.containsKey("definition"),"A new profile requires its definition");var config=body.containsKey("definition")?definition(db,body.get("definition")):object(before.get("definition"));if(before!=null && db.count("SELECT COUNT(*) FROM os_signed_receipt WHERE profile_id=?",id)>0 && !object(before.get("definition")).equals(config))throw new Failure(409,"A used profile keeps its original meaning; create a replacement");int active=Boolean.TRUE.equals(body.get("active"))?1:0;if(before==null){require(db.count("SELECT COUNT(*) FROM os_signed_profile")<100,"At most100 integration profiles are supported");id=Values.id();secret="osw_"+Passwords.token()+Passwords.token();db.update("INSERT INTO os_signed_profile(profile_id,name,table_name,gateway_id,definition,active,revision,envelope) VALUES(?,?,?,?,?,?,1,?)",id,config.get("name"),config.get("table"),config.get("gateway_id"),JSON.writeValueAsString(config),active,Outbox.encrypt(store.secret,JSON.writeValueAsString(map("secret",secret))));}else db.update("UPDATE os_signed_profile SET name=?,table_name=?,gateway_id=?,definition=?,active=?,revision=revision+1 WHERE profile_id=?",config.get("name"),config.get("table"),config.get("gateway_id"),JSON.writeValueAsString(config),active,id);}
  SecurityEvents.record(db,db.viewerId,db.viewerId,rotate?"integration.secret_rotated":"integration.profile_saved",map("profile_id",id));var result=page(db,id,Map.of());result.put("issued_secret",secret);return result;
 }
 static String header(List<String> values){require(values.size()==1,"Provide one value for each signed-event header");return values.getFirst();}
 static byte[] signature(String secret,String timestamp,String profile,String event,byte[] body)throws Exception {var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));mac.update((timestamp+"\n"+profile+"\n"+event+"\n").getBytes(StandardCharsets.UTF_8));return mac.doFinal(body);}
 static Map<String,Object> receive(Store store,Store.Db db,Map<String,Object> caller,String table,String id,String type,List<String> events,List<String> timestamps,List<String> signatures,byte[] bytes,long now)throws Exception {
  if(!caller.containsKey("api_key_id"))throw new Failure(403,"Use the configured gateway's scoped API key");if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var profile=profile(db,id);if(!profile.get("table_name").equals(table) || !profile.get("gateway_id").equals(caller.get("user_id")) || ((Number)profile.get("active")).intValue()!=1)throw new Failure(403,"Gateway is not enabled for this integration");InboundMail.gateway(db,caller.get("user_id").toString());if(type==null || !type.split(";",2)[0].strip().equalsIgnoreCase("application/json"))throw new Failure(415,"JSON content type is required");if(bytes.length>16384)throw new Failure(413,"Signed event exceeds16KB");String event=header(events),timestamp=header(timestamps),supplied=header(signatures);require(event.matches("[A-Za-z0-9._:@/-]{1,160}"),"Use a bounded event identity");require(timestamp.matches("0|[1-9][0-9]{0,11}"),"Use canonical epoch seconds");if(Math.abs(now/1000-Long.parseLong(timestamp))>300 || !supplied.matches("[0-9a-f]{64}"))throw new Failure(403,"Invalid or expired event signature");String secret;try{secret=Outbox.decrypt(store.secret,db.one("SELECT envelope FROM os_signed_profile WHERE profile_id=?",id).get("envelope").toString()).get("secret").toString();}catch(Exception unavailable){throw new Failure(503,"Integration signing key is unavailable");}if(!MessageDigest.isEqual(signature(secret,timestamp,id,event,bytes),HexFormat.of().parseHex(supplied)))throw new Failure(403,"Invalid or expired event signature");Object parsed;try{parsed=JSON.readValue(bytes,Object.class);}catch(tools.jackson.core.JacksonException invalid){throw new Failure(400,"Invalid JSON body");}var body=object(parsed);require(body.keySet().equals(Set.of("fields")),"Provide only record fields");var fields=object(body.get("fields"));require(!fields.isEmpty() && ((List<?>)object(profile.get("definition")).get("fields")).containsAll(fields.keySet()),"Use only this integration's allowed fields");Service.creationData(db,Service.schema(db,table),fields);String fingerprint=DigestUtils.sha256Hex(JSON.writeValueAsString(new TreeMap<>(fields)));var existing=db.one("SELECT fingerprint,record_id FROM os_signed_receipt WHERE profile_id=? AND event_id=?",id,event);if(existing!=null){if(!existing.get("fingerprint").equals(fingerprint))throw new Failure(409,"Event identity already represents different content");return map("record",FieldAccess.serialize(db,Service.readRecord(db,table,existing.get("record_id").toString())),"event_id",event,"duplicate",true);}require(db.count("SELECT COUNT(*) FROM os_signed_receipt WHERE profile_id=?",id)<10000,"Integration receipt capacity reached; operator review required");var record=Service.create(db,table,fields,caller.get("name").toString());db.update("INSERT INTO os_signed_receipt(profile_id,event_id,fingerprint,record_id,profile_revision,gateway_id,key_id,created) VALUES(?,?,?,?,?,?,?,?)",id,event,fingerprint,record.get("sys_id"),profile.get("revision"),caller.get("user_id"),caller.get("api_key_id"),ServiceOutages.stamp(now));Service.audit(db,record,caller.get("name").toString(),"integration.received",map("profile_id",id,"event_id",event));return map("record",FieldAccess.serialize(db,record),"event_id",event,"duplicate",false);
 }
}
